func (s *Scorch) introduceMerge(nextMerge *segmentMerge) {
	atomic.AddUint64(&s.stats.TotIntroduceMergeBeg, 1)
	defer atomic.AddUint64(&s.stats.TotIntroduceMergeEnd, 1)

	s.rootLock.RLock()
	root := s.root
	root.AddRef()
	s.rootLock.RUnlock()

	defer func() { _ = root.DecRef() }()

	newSnapshot := &IndexSnapshot{
		parent:   s,
		internal: root.internal,
		refs:     1,
		creator:  "introduceMerge",
	}

	var running, docsToPersistCount, memSegments, fileSegments uint64
	var droppedSegmentFiles []string
	newSegmentsDeleted := make([]*roaring.Bitmap, len(nextMerge.newSegments))
	for i := range newSegmentsDeleted {
		// create a bitmaps to track the obsoletes per newly merged segments
		newSegmentsDeleted[i] = roaring.NewBitmap()
	}

	// iterate through current segments
	for i := range root.segment {
		segmentID := root.segment[i].id
		if history, ok := nextMerge.mergedSegHistory[segmentID]; ok {
			// this segment is going away, see if anything else was deleted since we started the merge
			if history != nil && root.segment[i].deleted != nil {
				// assume all these deletes are new
				deletedSince := root.segment[i].deleted
				// if we already knew about some of them, remove
				if history.oldSegment.deleted != nil {
					deletedSince = roaring.AndNot(root.segment[i].deleted, history.oldSegment.deleted)
				}
				deletedSinceItr := deletedSince.Iterator()
				for deletedSinceItr.HasNext() {
					oldDocNum := deletedSinceItr.Next()
					newDocNum := history.oldNewDocIDs[oldDocNum]
					newSegmentsDeleted[history.batchID].Add(uint32(newDocNum))
				}
			}

			// clean up the old segment map to figure out the
			// obsolete segments wrt root in meantime, whatever
			// segments left behind in old map after processing
			// the root segments would be the obsolete segment set
			delete(nextMerge.mergedSegHistory, segmentID)
		} else if root.segment[i].LiveSize() > 0 {
			// this segment is staying
			newSnapshot.segment = append(newSnapshot.segment, &SegmentSnapshot{
				id:         root.segment[i].id,
				segment:    root.segment[i].segment,
				deleted:    root.segment[i].deleted,
				stats:      root.segment[i].stats,
				cachedDocs: root.segment[i].cachedDocs,
				cachedMeta: root.segment[i].cachedMeta,
				creator:    root.segment[i].creator,
			})
			root.segment[i].segment.AddRef()
			newSnapshot.offsets = append(newSnapshot.offsets, running)
			running += root.segment[i].segment.Count()

			if isMemorySegment(root.segment[i]) {
				docsToPersistCount += root.segment[i].Count()
				memSegments++
			} else {
				fileSegments++
			}
		} else if root.segment[i].LiveSize() == 0 {
			if seg, ok := root.segment[i].segment.(segment.PersistedSegment); ok {
				droppedSegmentFiles = append(droppedSegmentFiles,
					filepath.Base(seg.Path()))
			}
		}
	}
	// before the newMerge introduction, need to clean the newly
	// merged segment wrt the current root segments, hence
	// applying the obsolete segment contents to newly merged segment
	for _, ss := range nextMerge.mergedSegHistory {
		obsoleted := ss.oldSegment.DocNumbersLive()
		if obsoleted != nil {
			obsoletedIter := obsoleted.Iterator()
			for obsoletedIter.HasNext() {
				oldDocNum := obsoletedIter.Next()
				newDocNum := ss.oldNewDocIDs[oldDocNum]
				newSegmentsDeleted[ss.batchID].Add(uint32(newDocNum))
			}
		}
	}

	skipped := make([]bool, len(nextMerge.newSegments))
	// make the newly merged segments part of the newSnapshot being constructed
	for i, newMergedSegment := range nextMerge.newSegments {
		if newMergedSegment == nil {
			if nextMerge.fileMerge {
				atomic.AddUint64(&s.stats.TotFileMergeIntroductionsSkipped, 1)
			} else {
				atomic.AddUint64(&s.stats.TotMemMergeIntroductionsSkipped, 1)
			}
			skipped[i] = true
			continue
		}
		// checking if this newly merged segment is worth keeping based on
		// obsoleted doc count since the merge intro started
		if newMergedSegment.Count() > newSegmentsDeleted[i].GetCardinality() {
			stats := newFieldStats()
			if fsr, ok := newMergedSegment.(segment.FieldStatsReporter); ok {
				fsr.UpdateFieldStats(stats)
			}

			// put the merged segment at the end of newSnapshot
			newSnapshot.segment = append(newSnapshot.segment, &SegmentSnapshot{
				id:         nextMerge.newSegmentIDs[i],
				segment:    newMergedSegment, // take ownership for newMergedSegment's ref-count
				deleted:    newSegmentsDeleted[i],
				stats:      stats,
				cachedDocs: &cachedDocs{cache: nil},
				cachedMeta: newCachedMeta(),
				creator:    "introduceMerge",
				mmaped:     nextMerge.mmaped,
			})
			newSnapshot.offsets = append(newSnapshot.offsets, running)
			running += newMergedSegment.Count()

			switch newMergedSegment.(type) {
			case segment.PersistedSegment:
				fileSegments++
			default:
				docsToPersistCount += newMergedSegment.Count() - newSegmentsDeleted[i].GetCardinality()
				memSegments++
			}
			atomic.AddUint64(&s.stats.TotIntroducedSegmentsMerge, 1)
			skipped[i] = false
		} else {
			if nextMerge.fileMerge {
				atomic.AddUint64(&s.stats.TotFileMergeIntroductionsObsoleted, 1)
			} else {
				atomic.AddUint64(&s.stats.TotMemMergeIntroductionsObsoleted, 1)
			}
			skipped[i] = true
		}
	}

	atomic.StoreUint64(&s.stats.TotItemsToPersist, docsToPersistCount)
	atomic.StoreUint64(&s.stats.TotMemorySegmentsAtRoot, memSegments)
	atomic.StoreUint64(&s.stats.TotFileSegmentsAtRoot, fileSegments)

	newSnapshot.AddRef() // 1 ref for the nextMerge.notify response

	newSnapshot.updateSize()
	s.rootLock.Lock()
	// swap in new index snapshot
	newSnapshot.epoch = s.nextSnapshotEpoch
	s.nextSnapshotEpoch++
	rootPrev := s.root
	s.root = newSnapshot
	atomic.StoreUint64(&s.stats.CurRootEpoch, s.root.epoch)
	// release lock
	s.rootLock.Unlock()

	if rootPrev != nil {
		_ = rootPrev.DecRef()
	}

	// update the removal eligibility for those segment files
	// that are not a part of the latest root.
	for _, filename := range droppedSegmentFiles {
		s.unmarkIneligibleForRemoval(filename)
	}

	// notify requester that we incorporated this
	nextMerge.notifyCh <- &mergeTaskIntroStatus{
		indexSnapshot: newSnapshot,
		skipped:       skipped}
	close(nextMerge.notifyCh)
}

persister.defaults.code:
// DefaultPersisterNapTimeMSec is kept to zero as this helps in direct
// persistence of segments with the default safe batch option.
// If the default safe batch option results in high number of
// files on disk, then users may initialise this configuration parameter
// with higher values so that the persister will nap a bit within it's
// work loop to favour better in-memory merging of segments to result
// in fewer segment files on disk. But that may come with an indexing
// performance overhead.
// Unsafe batch users are advised to override this to higher value
// for better performance especially with high data density.
DefaultPersisterNapTimeMSec int = 0 // ms

// DefaultPersisterNapUnderNumFiles helps in controlling the pace of
// persister. At times of a slow merger progress with heavy file merging
// operations, its better to pace down the persister for letting the merger
// to catch up within a range defined by this parameter.
// Fewer files on disk (as per the merge plan) would result in keeping the
// file handle usage under limit, faster disk merger and a healthier index.
// Its been observed that such a loosely sync'ed introducer-persister-merger
// trio results in better overall performance.
DefaultPersisterNapUnderNumFiles int = 1000

// MemoryPressurePauseThreshold lets persister to have a better leeway
// for prudently performing the memory merge of segments on a memory
// pressure situation. Here the config value is an upper threshold
// for the number of paused application threads. The default value would
// be a very high number to always favour the merging of memory segments.
DefaultMemoryPressurePauseThreshold uint64 = math.MaxUint64

// DefaultMinSegmentsForInMemoryMerge represents the default number of
// in-memory zap segments that persistSnapshotMaybeMerge() needs to
// see in an IndexSnapshot before it decides to merge and persist
// those segments
DefaultMinSegmentsForInMemoryMerge int = 2

// number workers which parallely perform an in-memory merge of the segments
// followed by a flush operation.
DefaultNumPersisterWorkers int = 1

// maximum size of data that a single worker is allowed to perform the in-memory
// merge operation.
DefaultMaxSizeInMemoryMergePerWorker int = 0

// NumSnapshotsToKeep represents how many recent, old snapshots to
// keep around per Scorch instance.  Useful for apps that require
// rollback'ability.
NumSnapshotsToKeep int = 1

// RollbackSamplingInterval controls how far back we are looking
// in the history to get the rollback points.
// If we have to keep N snapshots ( = NumSnapshotsToKeep ), then upon
// including the very latest snapshot there should be N snapshots.
// If the timestamp of the latest snapshot is T, and the
// RollbackSamplingInterval is D, then the very last one would be T - (N - 1) * D
// A value of 0 means we will not sample, and will keep the very latest N snapshots.
// Example:
//  - For N = 3, and the below timing diagram:
//  	a     b     c     d
//  	|-----|-----|-----| --> time
//  	|  D  |  D  |  D  |
//  	X     Y     Z     T
// - The rollback points would be b, c, and d. a would be too old.
RollbackSamplingInterval time.Duration = 0

persister.loop.code:
func (s *Scorch) persisterLoop() {
	defer func() {
		if r := recover(); r != nil {
			s.fireAsyncError(NewScorchError(
				persister,
				fmt.Sprintf("panic: %v, path: %s", r, s.path),
				ErrAsyncPanic,
			))
		}

		s.asyncTasks.Done()
	}()

	var persistWatchers []*epochWatcher
	var lastPersistedEpoch, lastMergedEpoch uint64
	var ew *epochWatcher

	var unpersistedCallbacks []index.BatchCallback

OUTER:
	for {
		atomic.AddUint64(&s.stats.TotPersistLoopBeg, 1)

		select {
		case <-s.closeCh:
			break OUTER
		case ew = <-s.persisterNotifier:
			persistWatchers = append(persistWatchers, ew)
		default:
		}
		if ew != nil && ew.epoch > lastMergedEpoch {
			lastMergedEpoch = ew.epoch
		}
		lastMergedEpoch, persistWatchers = s.pausePersisterForMergerCatchUp(lastPersistedEpoch,
			lastMergedEpoch, persistWatchers, s.persisterOptions)

		var ourSnapshot *IndexSnapshot
		var ourPersisted []chan error
		var ourPersistedCallbacks []index.BatchCallback

		// check to see if there is a new snapshot to persist
		s.rootLock.Lock()
		if s.root != nil && s.root.epoch > lastPersistedEpoch {
			ourSnapshot = s.root
			ourSnapshot.AddRef()
			ourPersisted = s.rootPersisted
			s.rootPersisted = nil
			ourPersistedCallbacks = s.persistedCallbacks
			s.persistedCallbacks = nil
			atomic.StoreUint64(&s.iStats.persistSnapshotSize, uint64(ourSnapshot.Size()))
			atomic.StoreUint64(&s.iStats.persistEpoch, ourSnapshot.epoch)
		}
		s.rootLock.Unlock()

		if ourSnapshot != nil {
			startTime := time.Now()

			err := s.persistSnapshot(ourSnapshot, s.persisterOptions)
			for _, ch := range ourPersisted {
				if err != nil {
					ch <- err
				}
				close(ch)
			}
			if err != nil {
				atomic.StoreUint64(&s.iStats.persistEpoch, 0)
				if err == segment.ErrClosed {
					// index has been closed
					_ = ourSnapshot.DecRef()
					break OUTER
				}

				// save this current snapshot's persistedCallbacks, to invoke during
				// the retry attempt
				unpersistedCallbacks = append(unpersistedCallbacks, ourPersistedCallbacks...)

				s.fireAsyncError(NewScorchError(
					persister,
					fmt.Sprintf("got err persisting snapshot: %v", err),
					ErrPersist,
				))
				_ = ourSnapshot.DecRef()
				atomic.AddUint64(&s.stats.TotPersistLoopErr, 1)
				continue OUTER
			}

			if unpersistedCallbacks != nil {
				// in the event of this being a retry attempt for persisting a snapshot
				// that had earlier failed, prepend the persistedCallbacks associated
				// with earlier segment(s) to the latest persistedCallbacks
				ourPersistedCallbacks = append(unpersistedCallbacks, ourPersistedCallbacks...)
				unpersistedCallbacks = nil
			}

			for i := range ourPersistedCallbacks {
				ourPersistedCallbacks[i](err)
			}

			atomic.StoreUint64(&s.stats.LastPersistedEpoch, ourSnapshot.epoch)

			lastPersistedEpoch = ourSnapshot.epoch
			for _, ew := range persistWatchers {
				close(ew.notifyCh)
			}

			persistWatchers = nil
			_ = ourSnapshot.DecRef()

			changed := false
			s.rootLock.RLock()
			if s.root != nil && s.root.epoch != lastPersistedEpoch {
				changed = true
			}
			s.rootLock.RUnlock()

			s.fireEvent(EventKindPersisterProgress, time.Since(startTime))

			if changed {
				atomic.AddUint64(&s.stats.TotPersistLoopProgress, 1)
				continue OUTER
			}
		}

		// tell the introducer we're waiting for changes
		w := &epochWatcher{
			epoch:    lastPersistedEpoch,
			notifyCh: make(notificationChan, 1),
		}

		select {
		case <-s.closeCh:
			break OUTER
		case s.introducerNotifier <- w:
		}

		if ok := s.fireEvent(EventKindPurgerCheck, 0); ok {
			s.removeOldData() // might as well cleanup while waiting
		}

		atomic.AddUint64(&s.stats.TotPersistLoopWait, 1)

		select {
		case <-s.closeCh:
			break OUTER
		case <-w.notifyCh:
			// woken up, next loop should pick up work
			atomic.AddUint64(&s.stats.TotPersistLoopWaitNotified, 1)
		case ew = <-s.persisterNotifier:
			// if the watchers are already caught up then let them wait,
			// else let them continue to do the catch up
			persistWatchers = append(persistWatchers, ew)
		}

		atomic.AddUint64(&s.stats.TotPersistLoopEnd, 1)
	}
}

persister.pause.code:
func (s *Scorch) pausePersisterForMergerCatchUp(lastPersistedEpoch uint64,
	lastMergedEpoch uint64, persistWatchers []*epochWatcher,
	po *persisterOptions,
) (uint64, []*epochWatcher) {
	// First, let the watchers proceed if they lag behind
	persistWatchers = notifyMergeWatchers(lastPersistedEpoch, persistWatchers)

	// Check the merger lag by counting the segment files on disk,
	numFilesOnDisk, _, _ := s.diskFileStats(nil)

	// On finding fewer files on disk, persister takes a short pause
	// for sufficient in-memory segments to pile up for the next
	// memory merge cum persist loop.
	if numFilesOnDisk < uint64(po.PersisterNapUnderNumFiles) &&
		po.PersisterNapTimeMSec > 0 && s.NumEventsBlocking() == 0 {
		select {
		case <-s.closeCh:
		case <-time.After(time.Millisecond * time.Duration(po.PersisterNapTimeMSec)):
			atomic.AddUint64(&s.stats.TotPersisterNapPauseCompleted, 1)

		case ew := <-s.persisterNotifier:
			// unblock the merger in meantime
			persistWatchers = append(persistWatchers, ew)
			lastMergedEpoch = ew.epoch
			persistWatchers = notifyMergeWatchers(lastPersistedEpoch, persistWatchers)
			atomic.AddUint64(&s.stats.TotPersisterMergerNapBreak, 1)
		}
		return lastMergedEpoch, persistWatchers
	}

	// Finding too many files on disk could be due to two reasons.
	// 1. Too many older snapshots awaiting the clean up.
	// 2. The merger could be lagging behind on merging the disk files.
	if numFilesOnDisk > uint64(po.PersisterNapUnderNumFiles) {
		if ok := s.fireEvent(EventKindPurgerCheck, 0); ok {
			s.removeOldData()
		}
		numFilesOnDisk, _, _ = s.diskFileStats(nil)
	}

	// Persister pause until the merger catches up to reduce the segment
	// file count under the threshold.
	// But if there is memory pressure, then skip this sleep maneuvers.
OUTER:
	for po.PersisterNapUnderNumFiles > 0 &&
		numFilesOnDisk >= uint64(po.PersisterNapUnderNumFiles) &&
		lastMergedEpoch < lastPersistedEpoch {
		atomic.AddUint64(&s.stats.TotPersisterSlowMergerPause, 1)

		select {
		case <-s.closeCh:
			break OUTER
		case ew := <-s.persisterNotifier:
			persistWatchers = append(persistWatchers, ew)
			lastMergedEpoch = ew.epoch
		}

		atomic.AddUint64(&s.stats.TotPersisterSlowMergerResume, 1)

		// let the watchers proceed if they lag behind
		persistWatchers = notifyMergeWatchers(lastPersistedEpoch, persistWatchers)

		numFilesOnDisk, _, _ = s.diskFileStats(nil)
	}

	return lastMergedEpoch, persistWatchers
}

persister.persistSnapshot.code:
func (s *Scorch) persistSnapshot(snapshot *IndexSnapshot, po *persisterOptions) error {
	// Perform in-memory segment merging only when the memory pressure is
	// below the configured threshold, else the persister performs the
	// direct persistence of segments.
	if s.NumEventsBlocking() < po.MemoryPressurePauseThreshold {
		persisted, err := s.persistSnapshotMaybeMerge(snapshot, po)
		if err != nil {
			return err
		}
		if persisted {
			return nil
		}
	}

	return s.persistSnapshotDirect(snapshot)
}

persister.maybeMerge.code:
func (s *Scorch) persistSnapshotMaybeMerge(snapshot *IndexSnapshot, po *persisterOptions) (
	bool, error) {
	// split our segment snapshots into unpersisted and persisted segments
	var persistedSegments []*SegmentSnapshot
	var unpersistedSegments []*SegmentSnapshot
	numSegments := len(snapshot.segment)

	// collect details of the unpersisted segments
	sbs := make([]segment.Segment, 0, numSegments)
	sbsDrops := make([]*roaring.Bitmap, 0, numSegments)
	sbsSizes := make([]int, 0, numSegments)
	for _, segmentSnapshot := range snapshot.segment {
		if _, ok := segmentSnapshot.segment.(segment.PersistedSegment); ok {
			persistedSegments = append(persistedSegments, segmentSnapshot)
		} else {
			unpersistedSegments = append(unpersistedSegments, segmentSnapshot)
			sbs = append(sbs, segmentSnapshot.segment)
			sbsDrops = append(sbsDrops, segmentSnapshot.deleted)
			sbsSizes = append(sbsSizes, segmentSnapshot.Size())
		}
	}
	numPersistedSegments := len(persistedSegments)
	numUnpersistedSegments := len(unpersistedSegments)

	// if we don't have enough segments to persist, then just return
	if numUnpersistedSegments < DefaultMinSegmentsForInMemoryMerge {
		return false, nil
	}

	// create our flushSet, which will be an array of flushable objects,
	// each of which will be a batch of segments to merge and persist.
	// We are guaranteed that at least one flushable object will be created,
	// since we have already ensured that at least one unpersisted segment is present.
	var flushSet []*flushable
	if legacyFlushBehaviour(po.MaxSizeInMemoryMergePerWorker, po.NumPersisterWorkers) {
		val := &flushable{
			sbsBatch:          slices.Clone(sbs),
			sbsBatchDrops:     slices.Clone(sbsDrops),
			sbsBatchSnapshots: slices.Clone(unpersistedSegments),
		}
		flushSet = append(flushSet, val)
	} else {
		sbsBatch := make([]segment.Segment, 0, numUnpersistedSegments)
		sbsBatchDrops := make([]*roaring.Bitmap, 0, numUnpersistedSegments)
		sbsBatchSnapshots := make([]*SegmentSnapshot, 0, numUnpersistedSegments)
		runningSize := 0
		for i := 0; i < numUnpersistedSegments; i++ {
			sbsBatch = append(sbsBatch, sbs[i])
			sbsBatchDrops = append(sbsBatchDrops, sbsDrops[i])
			sbsBatchSnapshots = append(sbsBatchSnapshots, unpersistedSegments[i])
			runningSize += sbsSizes[i]
			if runningSize >= po.MaxSizeInMemoryMergePerWorker && len(sbsBatch) >= DefaultMinSegmentsForInMemoryMerge {
				flushSet = append(flushSet, &flushable{
					sbsBatch:          slices.Clone(sbsBatch),
					sbsBatchDrops:     slices.Clone(sbsBatchDrops),
					sbsBatchSnapshots: slices.Clone(sbsBatchSnapshots),
				})
				sbsBatch, sbsBatchDrops, sbsBatchSnapshots = sbsBatch[:0], sbsBatchDrops[:0], sbsBatchSnapshots[:0]
				runningSize = 0
			}
		}
		if len(sbsBatch) > 0 {
			flushSet = append(flushSet, &flushable{
				sbsBatch:          slices.Clone(sbsBatch),
				sbsBatchDrops:     slices.Clone(sbsBatchDrops),
				sbsBatchSnapshots: slices.Clone(sbsBatchSnapshots),
			})
		}
	}

	// now merge each batch into a new segment, and persist all of them to disk,
	// and construct a new snapshot with the merged segments
	newSnapshot, newSegmentIDs, err := s.mergeAndPersistInMemorySegments(flushSet, po)
	if err != nil {
		return false, err
	}
	if newSnapshot == nil {
		return false, nil
	}
	defer func() {
		_ = newSnapshot.DecRef()
	}()

	// construct a snapshot that's logically equivalent to the input
	// snapshot, but with merged segments replaced by the new segment
	equiv := &IndexSnapshot{
		parent:   snapshot.parent,
		segment:  make([]*SegmentSnapshot, 0, numPersistedSegments+len(newSegmentIDs)),
		internal: snapshot.internal,
		epoch:    snapshot.epoch,
		creator:  "persistSnapshotMaybeMerge",
	}

	// first add all the segments that were already persisted
	// and did not participate in the merge
	for _, segment := range persistedSegments {
		equiv.segment = append(equiv.segment, segment)
	}

	// next, add all the segments that were unpersisted and hence
	// participated in the merge, from the merged snapshot
	for _, segment := range newSnapshot.segment {
		if _, ok := newSegmentIDs[segment.id]; ok {
			equiv.segment = append(equiv.segment, &SegmentSnapshot{
				id:      segment.id,
				segment: segment.segment,
				deleted: nil, // nil since merging handled deletions
				stats:   segment.stats,
			})
		}
	}

	// finally, persist the equivalent snapshot to disk
	err = s.persistSnapshotDirect(equiv)
	if err != nil {
		return false, err
	}

	return true, nil
}

persister.direct.code:
func (s *Scorch) persistSnapshotDirect(snapshot *IndexSnapshot) (err error) {
	// start a write transaction
	tx, err := s.rootBolt.Begin(true)
	if err != nil {
		return err
	}
	// defer rollback on error
	defer func() {
		if err != nil {
			_ = tx.Rollback()
		}
	}()

	filenames, newSegmentPaths, err := prepareBoltSnapshot(snapshot, tx, s.path, s.segPlugin, nil)
	if err != nil {
		return err
	}

	// we need to swap in a new root only when we've persisted 1 or
	// more segments -- whereby the new root would have 1-for-1
	// replacements of in-memory segments with file-based segments
	//
	// other cases like updates to internal values only, and/or when
	// there are only deletions, are already covered and persisted by
	// the newly populated boltdb snapshotBucket above
	if len(newSegmentPaths) > 0 {
		// now try to open all the new snapshots
		newSegments := make(map[uint64]segment.Segment, len(newSegmentPaths))
		defer func() {
			for _, s := range newSegments {
				if s != nil {
					// cleanup segments that were opened but not
					// swapped into the new root
					_ = s.Close()
				}
			}
		}()
		for segmentID, path := range newSegmentPaths {
			newSegments[segmentID], err = s.segPlugin.OpenUsing(path, s.segmentConfig)
			if err != nil {
				return fmt.Errorf("error opening new segment at %s, %v", path, err)
			}
		}

		persist := &persistIntroduction{
			persisted: newSegments,
			applied:   make(notificationChan),
		}

		select {
		case <-s.closeCh:
			return segment.ErrClosed
		case s.persists <- persist:
		}

		// blockingly wait until the persist has been applied
		<-persist.applied
	}

	err = tx.Commit()
	if err != nil {
		return err
	}

	err = s.rootBolt.Sync()
	if err != nil {
		return err
	}

	// allow files to become eligible for removal after commit, such
	// as file segments from snapshots that came from the merger
	s.rootLock.Lock()
	for _, filename := range filenames {
		delete(s.ineligibleForRemoval, filename)
	}
	s.rootLock.Unlock()

	return nil
}

persister.removeOldData.code:
func (s *Scorch) removeOldData() {
	removed, err := s.removeOldBoltSnapshots()
	if err != nil {
		s.fireAsyncError(NewScorchError(
			persister,
			fmt.Sprintf("got err removing old bolt snapshots: %v", err),
			ErrCleanup,
		))
	}
	atomic.AddUint64(&s.stats.TotSnapshotsRemovedFromMetaStore, uint64(removed))

	err = s.removeOldZapFiles()
	if err != nil {
		s.fireAsyncError(NewScorchError(
			persister,
			fmt.Sprintf("got err removing old zap files: %v", err),
			ErrCleanup,
		))
	}
}

persister.protected.code:
func (s *Scorch) getProtectedSnapshots(liveSnapshots []*snapshotMetaData) map[uint64]time.Time {
	// keep numSnapshotsToKeep - 1 worth of time series snapshots, because we always
	// must preserve the very latest snapshot in bolt as well to avoid accidental
	// deletes of bolt entries and cleanups by the purger code.
	protectedEpochs := getTimeSeriesSnapshots(s.numSnapshotsToKeep-1,
		s.rollbackSamplingInterval, liveSnapshots)
	numProtected := len(protectedEpochs)
	// always protect the latest snapshot
	latestSnapshot := liveSnapshots[0]
	if _, ok := protectedEpochs[latestSnapshot.epoch]; !ok {
		protectedEpochs[latestSnapshot.epoch] = latestSnapshot.timeStamp
		numProtected++
	}
	// if we still have not protected enough snapshots, then protect the next most recent snapshots
	for i := 1; i < len(liveSnapshots) && numProtected < s.numSnapshotsToKeep; i++ {
		if _, ok := protectedEpochs[liveSnapshots[i].epoch]; !ok {
			protectedEpochs[liveSnapshots[i].epoch] = liveSnapshots[i].timeStamp
			numProtected++
		}
	}
	return protectedEpochs
}

persister.removeOldZapFiles.code:
func (s *Scorch) removeOldZapFiles() error {
	liveFileNames, err := s.loadZapFileNames()
	if err != nil {
		return err
	}

	files, err := os.ReadDir(s.path)
	if err != nil {
		return err
	}

	s.rootLock.RLock()

	for _, f := range files {
		fname := f.Name()
		if filepath.Ext(fname) == ".zap" {
			if _, exists := liveFileNames[fname]; !exists && !s.ineligibleForRemoval[fname] && (s.copyScheduled[fname] <= 0) {
				err := os.Remove(s.path + string(os.PathSeparator) + fname)
				if err != nil {
					log.Printf("got err removing file: %s, err: %v", fname, err)
				}
			}
		}
	}

	s.rootLock.RUnlock()

	return nil
}

merger.loop.code:
func (s *Scorch) mergerLoop() {
	defer func() {
		if r := recover(); r != nil {
			s.fireAsyncError(NewScorchError(
				merger,
				fmt.Sprintf("panic: %v, path: %s", r, s.path),
				ErrAsyncPanic,
			))
		}

		s.asyncTasks.Done()
	}()

	var lastEpochMergePlanned uint64
	var ctrlMsg *mergerCtrl
	ctrlMsgDflt := &mergerCtrl{ctx: context.Background(),
		options: s.mergePlannerOptions,
		doneCh:  nil}

OUTER:
	for {
		atomic.AddUint64(&s.stats.TotFileMergeLoopBeg, 1)

		select {
		case <-s.closeCh:
			break OUTER

		default:
			// check to see if there is a new snapshot to persist
			s.rootLock.Lock()
			ourSnapshot := s.root
			ourSnapshot.AddRef()
			atomic.StoreUint64(&s.iStats.mergeSnapshotSize, uint64(ourSnapshot.Size()))
			atomic.StoreUint64(&s.iStats.mergeEpoch, ourSnapshot.epoch)
			s.rootLock.Unlock()

			if ctrlMsg == nil && ourSnapshot.epoch != lastEpochMergePlanned {
				ctrlMsg = ctrlMsgDflt
			}
			if ctrlMsg != nil {
				continueMerge := s.fireEvent(EventKindPreMergeCheck, 0)
				// The default, if there's no handler, is to continue the merge.
				if !continueMerge {
					// If it's decided that this merge can't take place now,
					// begin the merge process all over again.
					// Retry instead of blocking/waiting here since a long wait
					// can result in more segments introduced i.e. s.root will
					// be updated.

					// decrement the ref count since its no longer needed in this
					// iteration
					_ = ourSnapshot.DecRef()
					continue OUTER
				}

				// lets get started
				startTime := time.Now()
				err := s.planMergeAtSnapshot(ctrlMsg, ourSnapshot)
				if err != nil {
					atomic.StoreUint64(&s.iStats.mergeEpoch, 0)
					if err == segment.ErrClosed {
						// index has been closed
						_ = ourSnapshot.DecRef()

						// continue the workloop on a user triggered cancel
						if ctrlMsg.doneCh != nil {
							close(ctrlMsg.doneCh)
							ctrlMsg = nil
							continue OUTER
						}

						// exit the workloop on index closure
						ctrlMsg = nil
						break OUTER
					}

					s.fireAsyncError(NewScorchError(
						merger,
						fmt.Sprintf("merging err: %v", err),
						ErrPersist,
					))
					_ = ourSnapshot.DecRef()
					atomic.AddUint64(&s.stats.TotFileMergeLoopErr, 1)
					continue OUTER
				}

				if ctrlMsg.doneCh != nil {
					close(ctrlMsg.doneCh)
				}
				ctrlMsg = nil

				lastEpochMergePlanned = ourSnapshot.epoch

				atomic.StoreUint64(&s.stats.LastMergedEpoch, ourSnapshot.epoch)

				s.fireEvent(EventKindMergerProgress, time.Since(startTime))
			}
			_ = ourSnapshot.DecRef()

			// tell the persister we're waiting for changes
			// first make a epochWatcher chan
			ew := &epochWatcher{
				epoch:    lastEpochMergePlanned,
				notifyCh: make(notificationChan, 1),
			}

			// give it to the persister
			select {
			case <-s.closeCh:
				break OUTER
			case s.persisterNotifier <- ew:
			case ctrlMsg = <-s.forceMergeRequestCh:
				continue OUTER
			}

			// now wait for persister (but also detect close)
			select {
			case <-s.closeCh:
				break OUTER
			case <-ew.notifyCh:
			case ctrlMsg = <-s.forceMergeRequestCh:
			}
		}

		atomic.AddUint64(&s.stats.TotFileMergeLoopEnd, 1)
	}
}

merger.planMergeAtSnapshot.code:
func (s *Scorch) planMergeAtSnapshot(ctrlMsg *mergerCtrl, ourSnapshot *IndexSnapshot) error {
	var mergePlan *mergeplan.MergePlan
	// if a merge plan function is provided in the context, use it to get the merge plan
	if mergePlanFunc, ok := ctrlMsg.ctx.Value(mergePlanFuncKey).(mergePlanFunc); ok {
		var err error
		mergePlan, err = mergePlanFunc(ourSnapshot)
		if err != nil {
			atomic.AddUint64(&s.stats.TotFileMergePlanErr, 1)
			return fmt.Errorf("merge planning err: %v", err)
		}
	}

	// default to making a merge plan if a custom one is not provided
	if mergePlan == nil || len(mergePlan.Tasks) == 0 {
		// build list of persisted segments in this snapshot
		var onlyPersistedSnapshots []mergeplan.Segment
		for _, segmentSnapshot := range ourSnapshot.segment {
			if _, ok := segmentSnapshot.segment.(segment.PersistedSegment); ok {
				onlyPersistedSnapshots = append(onlyPersistedSnapshots, segmentSnapshot)
			}
		}

		atomic.AddUint64(&s.stats.TotFileMergePlan, 1)

		// give this list to the planner
		var err error
		mergePlan, err = mergeplan.Plan(onlyPersistedSnapshots, ctrlMsg.options)
		if err != nil {
			atomic.AddUint64(&s.stats.TotFileMergePlanErr, 1)
			return fmt.Errorf("merge planning err: %v", err)
		}

		if mergePlan == nil || len(mergePlan.Tasks) == 0 {
			// nothing to do
			atomic.AddUint64(&s.stats.TotFileMergePlanNone, 1)
			return nil
		}
	}

	atomic.AddUint64(&s.stats.TotFileMergePlanOk, 1)
	atomic.AddUint64(&s.stats.TotFileMergePlanTasks, uint64(len(mergePlan.Tasks)))

	cw := newCloseChWrapper(s.closeCh, ctrlMsg.ctx)
	defer cw.close()
	go cw.listen()

	var err error
	defer func() {
		// send error to done channel if present
		if done, ok := cw.ctx.Value(mergeDoneKey).(chan error); ok {
			done <- err
		}
	}()

	numBatches := len(mergePlan.Tasks)
	mergeBatches := make([]*mergeBatch, numBatches)
	defer func() {
		for batchID := 0; batchID < numBatches; batchID++ {
			batch := mergeBatches[batchID]
			if batch == nil {
				continue
			}
			if err == nil {
				s.rootLock.Lock()
				for _, filename := range batch.filenames {
					delete(s.ineligibleForRemoval, filename)
				}
				s.rootLock.Unlock()
			} else {
				if batch.new != nil {
					_ = batch.new.Close()
				}
				s.unmarkIneligibleForRemoval(batch.newFilename)
			}
		}
	}()

	numMergedSegments := 0
	for batchID := 0; batchID < numBatches; batchID++ {
		task := mergePlan.Tasks[batchID]
		if len(task.Segments) == 0 {
			atomic.AddUint64(&s.stats.TotFileMergePlanTasksSegmentsEmpty, 1)
		}
		atomic.AddUint64(&s.stats.TotFileMergePlanTasksSegments, uint64(len(task.Segments)))

		newSegmentID := atomic.AddUint64(&s.nextSegmentID, 1)
		batch := &mergeBatch{
			snapshots: make([]*SegmentSnapshot, 0, len(task.Segments)),
			filenames: make([]string, 0, len(task.Segments)),
			segments:  make([]segment.Segment, 0, len(task.Segments)),
			drops:     make([]*roaring.Bitmap, 0, len(task.Segments)),

			new:         nil,
			newID:       newSegmentID,
			newDocNums:  nil,
			newFilename: zapFileName(newSegmentID),
			newTime:     0,
		}
		mergeBatches[batchID] = batch

		for _, planSegment := range task.Segments {
			if segSnapshot, ok := planSegment.(*SegmentSnapshot); ok {
				if persistedSeg, ok := segSnapshot.segment.(segment.PersistedSegment); ok {
					if segSnapshot.LiveSize() == 0 {
						atomic.AddUint64(&s.stats.TotFileMergeSegmentsEmpty, 1)
					} else {
						batch.snapshots = append(batch.snapshots, segSnapshot)
						batch.segments = append(batch.segments, segSnapshot.segment)
						batch.drops = append(batch.drops, segSnapshot.deleted)
					}
					// track the files getting merged for unsetting the
					// removal ineligibility. This helps to unflip files
					// even with fast merger, slow persister work flows.
					path := persistedSeg.Path()
					batch.filenames = append(batch.filenames,
						strings.TrimPrefix(path, s.path+string(os.PathSeparator)))
				}
			}
		}

		if len(batch.segments) == 0 {
			continue
		}

		numMergedSegments += len(batch.snapshots)
		s.markIneligibleForRemoval(batch.newFilename)
		path := s.path + string(os.PathSeparator) + batch.newFilename

		prevBytesReadTotal := cumulateBytesRead(batch.segments)
		fileMergeZapStartTime := time.Now()
		atomic.AddUint64(&s.stats.TotFileMergeZapBeg, 1)
		batch.newDocNums, _, err = s.segPlugin.MergeUsing(batch.segments, batch.drops, path,
			cw.cancelCh, s, s.segmentConfig)
		atomic.AddUint64(&s.stats.TotFileMergeZapEnd, 1)
		batch.newTime = uint64(time.Since(fileMergeZapStartTime))
		atomic.AddUint64(&s.stats.TotFileMergeZapTime, batch.newTime)
		if atomic.LoadUint64(&s.stats.MaxFileMergeZapTime) < batch.newTime {
			atomic.StoreUint64(&s.stats.MaxFileMergeZapTime, batch.newTime)
		}
		if err != nil {
			atomic.AddUint64(&s.stats.TotFileMergePlanTasksErr, 1)
			return err
		}

		batch.new, err = s.segPlugin.OpenUsing(path, s.segmentConfig)
		if err != nil {
			atomic.AddUint64(&s.stats.TotFileMergePlanTasksErr, 1)
			return err
		}

		totalBytesRead := batch.new.BytesRead() + prevBytesReadTotal
		batch.new.ResetBytesRead(totalBytesRead)
		atomic.AddUint64(&s.stats.TotFileMergeSegments, uint64(len(batch.segments)))
	}

	newSegmentIDs := make([]uint64, numBatches)
	newSegments := make([]segment.Segment, numBatches)
	mergedSegHistory := make(map[uint64]*mergedSegmentHistory, numMergedSegments)
	for batchID := 0; batchID < numBatches; batchID++ {
		batch := mergeBatches[batchID]
		newSegmentIDs[batchID] = batch.newID
		newSegments[batchID] = batch.new
		for j, ss := range batch.snapshots {
			mergedSegHistory[ss.id] = &mergedSegmentHistory{
				batchID:      batchID,
				oldNewDocIDs: batch.newDocNums[j],
				oldSegment:   ss,
			}
		}
	}

	sm := &segmentMerge{
		newSegmentIDs:    newSegmentIDs,
		newSegments:      newSegments,
		mergedSegHistory: mergedSegHistory,
		notifyCh:         make(chan *mergeTaskIntroStatus),
		mmaped:           1,
		fileMerge:        true,
	}

	s.fireEvent(EventKindMergeTaskIntroductionStart, 0)
	// give it to the introducer
	select {
	case <-s.closeCh:
		err = segment.ErrClosed
		return err
	case s.merges <- sm:
		atomic.AddUint64(&s.stats.TotFileMergeIntroductions, uint64(numBatches))
	}

	introStartTime := time.Now()
	// it is safe to blockingly wait for the merge introduction
	// here as the introducer is bound to handle the notify channel.
	introStatus := <-sm.notifyCh
	introTime := uint64(time.Since(introStartTime))
	atomic.AddUint64(&s.stats.TotFileMergeZapIntroductionTime, introTime)
	if atomic.LoadUint64(&s.stats.MaxFileMergeZapIntroductionTime) < introTime {
		atomic.StoreUint64(&s.stats.MaxFileMergeZapIntroductionTime, introTime)
	}
	atomic.AddUint64(&s.stats.TotFileMergeIntroductionsDone, uint64(numBatches))

	_ = introStatus.indexSnapshot.DecRef()
	for batchID, skipped := range introStatus.skipped {
		if skipped {
			batch := mergeBatches[batchID]
			if batch.new != nil {
				_ = batch.new.Close()
			}
			s.unmarkIneligibleForRemoval(batch.newFilename)
		}
	}

	atomic.AddUint64(&s.stats.TotFileMergePlanTasksDone, uint64(numBatches))
	s.fireEvent(EventKindMergeTaskIntroduction, 0)
	return nil
}

merger.memMerge.code:
func (s *Scorch) mergeAndPersistInMemorySegments(flushes []*flushable, po *persisterOptions) (*IndexSnapshot, map[uint64]struct{}, error) {
	atomic.AddUint64(&s.stats.TotMemMergeBeg, 1)

	var err error
	numBatches := len(flushes)
	mergeBatches := make([]*mergeBatch, numBatches)
	defer func() {
		if err != nil {
			for batchID := 0; batchID < numBatches; batchID++ {
				batch := mergeBatches[batchID]
				if batch.new != nil {
					_ = batch.new.Close()
				}
				s.unmarkIneligibleForRemoval(batch.newFilename)
			}
		}
	}()

	var numMergedSegments uint64
	sem := make(chan struct{}, po.NumPersisterWorkers)
	var wg sync.WaitGroup
	var errM sync.Mutex
	var errs []error
	for batchID := 0; batchID < numBatches; batchID++ {
		wg.Add(1)
		sem <- struct{}{}
		go func(batchID int) {
			var err error
			defer func() {
				if err != nil {
					atomic.AddUint64(&s.stats.TotMemMergeErr, 1)
					errM.Lock()
					errs = append(errs, err)
					errM.Unlock()
				}
				<-sem
				wg.Done()
			}()

			flush := flushes[batchID]
			newSegmentID := atomic.AddUint64(&s.nextSegmentID, 1)
			batch := &mergeBatch{
				snapshots: flush.sbsBatchSnapshots,
				filenames: nil,
				segments:  flush.sbsBatch,
				drops:     flush.sbsBatchDrops,

				new:         nil,
				newID:       newSegmentID,
				newDocNums:  nil,
				newFilename: zapFileName(newSegmentID),
				newTime:     0,
			}
			mergeBatches[batchID] = batch

			s.markIneligibleForRemoval(batch.newFilename)
			path := s.path + string(os.PathSeparator) + batch.newFilename

			memMergeZapStartTime := time.Now()
			atomic.AddUint64(&s.stats.TotMemMergeZapBeg, 1)
			batch.newDocNums, _, err = s.segPlugin.MergeUsing(batch.segments, batch.drops, path,
				s.closeCh, s, s.segmentConfig)
			atomic.AddUint64(&s.stats.TotMemMergeZapEnd, 1)
			batch.newTime = uint64(time.Since(memMergeZapStartTime))
			atomic.AddUint64(&s.stats.TotMemMergeZapTime, batch.newTime)
			if err != nil {
				return
			}
			batch.new, err = s.segPlugin.OpenUsing(path, s.segmentConfig)
			if err != nil {
				return
			}
			atomic.AddUint64(&numMergedSegments, uint64(len(batch.segments)))
		}(batchID)
	}
	wg.Wait()
	close(sem)

	var maxZapTime uint64
	for _, batch := range mergeBatches {
		if batch.newTime > maxZapTime {
			maxZapTime = batch.newTime
		}
	}
	if maxZapTime > atomic.LoadUint64(&s.stats.MaxMemMergeZapTime) {
		atomic.StoreUint64(&s.stats.MaxMemMergeZapTime, maxZapTime)
	}
	atomic.AddUint64(&s.stats.TotMemMergeSegments, numMergedSegments)

	if len(errs) > 0 {
		var errf error
		numClosed := 0
		for _, e := range errs {
			if e == segment.ErrClosed {
				numClosed++
			}
			errf = errors.Join(errf, e)
		}
		if numClosed == len(errs) {
			// the index snapshot was closed which will be handled gracefully
			// by retrying the whole merge+flush operation in a later iteration
			// so its safe to early exit the same error.
			err = segment.ErrClosed
		} else {
			err = errf
		}
		return nil, nil, err
	}

	newSegmentIDs := make([]uint64, numBatches)
	newSegments := make([]segment.Segment, numBatches)
	mergedSegHistory := make(map[uint64]*mergedSegmentHistory, numMergedSegments)
	for batchID := 0; batchID < numBatches; batchID++ {
		batch := mergeBatches[batchID]
		newSegmentIDs[batchID] = batch.newID
		newSegments[batchID] = batch.new
		for j, ss := range batch.snapshots {
			mergedSegHistory[ss.id] = &mergedSegmentHistory{
				batchID:      batchID,
				oldNewDocIDs: batch.newDocNums[j],
				oldSegment:   ss,
			}
		}
	}

	sm := &segmentMerge{
		newSegmentIDs:    newSegmentIDs,
		newSegments:      newSegments,
		mergedSegHistory: mergedSegHistory,
		notifyCh:         make(chan *mergeTaskIntroStatus),
		mmaped:           1,
		fileMerge:        false,
	}

	select {
	case <-s.closeCh:
		err = segment.ErrClosed
		return nil, nil, err
	case s.merges <- sm:
		atomic.AddUint64(&s.stats.TotMemMergeIntroductions, uint64(numBatches))
	}

	introStartTime := time.Now()
	// blockingly wait for the introduction to complete
	introStatus := <-sm.notifyCh
	introTime := uint64(time.Since(introStartTime))
	atomic.AddUint64(&s.stats.TotMemMergeZapIntroductionTime, introTime)
	if atomic.LoadUint64(&s.stats.MaxMemMergeZapIntroductionTime) < introTime {
		atomic.StoreUint64(&s.stats.MaxMemMergeZapIntroductionTime, introTime)
	}
	atomic.AddUint64(&s.stats.TotMemMergeIntroductionsDone, uint64(numBatches))
	introducedSnapshot := introStatus.indexSnapshot
	introducedSegmentIDs := make(map[uint64]struct{}, numBatches)
	for batchID, skipped := range introStatus.skipped {
		batch := mergeBatches[batchID]
		if skipped {
			_ = batch.new.Close()
			s.unmarkIneligibleForRemoval(batch.newFilename)
		} else {
			introducedSegmentIDs[batch.newID] = struct{}{}
		}
	}

	atomic.AddUint64(&s.stats.TotMemMergeDone, 1)

	// if we could not introduce all of the newly merged segments,
	// then we cannot persist a snapshot with any merged segments at all
	if len(introducedSegmentIDs) != numBatches {
		_ = introducedSnapshot.DecRef()
		return nil, nil, nil
	}

	return introducedSnapshot, introducedSegmentIDs, nil
}

mergeplan.plan.code:
func plan(segmentsIn []Segment, o *MergePlanOptions) (*MergePlan, error) {
	if len(segmentsIn) <= 1 {
		return nil, nil
	}

	if o == nil {
		o = &DefaultMergePlanOptions
	}

	segments := append([]Segment(nil), segmentsIn...) // Copy.

	sort.Sort(byLiveSizeDescending(segments))

	var minLiveSize int64 = math.MaxInt64
	var minLiveFileSize int64 = math.MaxInt64

	var eligibles []Segment
	var eligiblesLiveSize int64
	var eligiblesLiveFileSize int64

	for _, segment := range segments {
		liveSize := segment.LiveSize()
		liveFileSize := segment.LiveFileSize()

		if minLiveSize > liveSize {
			minLiveSize = liveSize
		}

		if minLiveFileSize > liveFileSize {
			minLiveFileSize = liveFileSize
		}

		isEligible := liveSize < o.MaxSegmentSize/2
		// An eligible segment (based on #documents) may be too large
		// and thus need a stricter check based on the file size.
		// This is particularly important for segments that contain
		// vectors.
		if segment.HasVector() {
			isEligible = isEligible && liveFileSize < o.MaxSegmentFileSize/2
		}

		// Only small-enough segments are eligible.
		if isEligible {
			eligibles = append(eligibles, segment)
			eligiblesLiveSize += liveSize
			eligiblesLiveFileSize += liveFileSize
		}
	}

	calcBudget := o.CalcBudget
	if calcBudget == nil {
		calcBudget = CalcBudget
	}

	currency := o.BudgetCurrency()

	var budgetNumSegments int
	switch currency {
	case FileSizeBudget:
		minLiveFileSize = o.RaiseToFloorSegmentFileSize(minLiveFileSize)
		budgetNumSegments = calcBudget(eligiblesLiveFileSize, minLiveFileSize, o)
	case LiveSizeBudget:
		minLiveSize = o.RaiseToFloorSegmentSize(minLiveSize)
		budgetNumSegments = calcBudget(eligiblesLiveSize, minLiveSize, o)
	default:
		return nil, ErrUnknownCurrency
	}

	scoreSegments := o.ScoreSegments
	if scoreSegments == nil {
		scoreSegments = ScoreSegments
	}

	rv := &MergePlan{}

	var empties []Segment
	for _, eligible := range eligibles {
		if eligible.LiveSize() <= 0 {
			empties = append(empties, eligible)
		}
	}
	if len(empties) > 0 {
		rv.Tasks = append(rv.Tasks, &MergeTask{Segments: empties})
		eligibles = removeSegments(eligibles, empties)
	}

	numMergeTasks := 0

	// While we're over budget, keep looping, which might produce
	// another MergeTask.
	for len(eligibles) > 0 && (len(eligibles)+numMergeTasks) > budgetNumSegments {
		// Track the current best candidate as we examine and score
		// potential rosters of merges.
		var best *rosterCandidate

		for startIdx := 0; startIdx < len(eligibles); startIdx++ {
			var roster []Segment
			var rosterLiveSize int64
			var rosterLiveFileSize int64

			for idx := startIdx; idx < len(eligibles) && len(roster) < o.SegmentsPerMergeTask; idx++ {
				eligible := eligibles[idx]

				liveSize := eligible.LiveSize()

				if rosterLiveSize+liveSize >= o.MaxSegmentSize {
					continue
				}

				if eligible.HasVector() {
					liveFileSize := eligible.LiveFileSize()

					if rosterLiveFileSize+liveFileSize >= o.MaxSegmentFileSize {
						continue
					}

					rosterLiveFileSize += liveFileSize
				}

				roster = append(roster, eligible)

				rosterLiveSize += liveSize
			}

			if len(roster) > 0 {
				rosterScore := scoreSegments(roster, o)

				candidate := &rosterCandidate{
					segments: roster,
					score:    rosterScore,
				}

				if best == nil || candidate.betterThan(best) {
					best = candidate
				}
			}
		}

		if best == nil {
			return rv, nil
		}

		bestRoster := best.segments

		// create tasks with valid merges - i.e. there should be at least 2 non-empty segments
		// or the bestRoster should have 1 segment with deletes to reclaim.
		if len(bestRoster) > 1 || bestRoster[0].LiveSize() < bestRoster[0].FullSize() {
			rv.Tasks = append(rv.Tasks, &MergeTask{Segments: bestRoster})
			numMergeTasks++
		}

		eligibles = removeSegments(eligibles, bestRoster)
	}

	return rv, nil
}

mergeplan.CalcBudget.code:
func CalcBudget(totalSize int64, firstTierSize int64, o *MergePlanOptions) (
	budgetNumSegments int) {
	tierSize := firstTierSize
	if tierSize < 1 {
		tierSize = 1
	}

	maxSegmentsPerTier := o.MaxSegmentsPerTier
	if maxSegmentsPerTier < 1 {
		maxSegmentsPerTier = 1
	}

	tierGrowth := o.TierGrowth
	if tierGrowth < 1.0 {
		tierGrowth = 1.0
	}

	for totalSize > 0 {
		segmentsInTier := float64(totalSize) / float64(tierSize)
		if segmentsInTier < float64(maxSegmentsPerTier) {
			budgetNumSegments += int(math.Ceil(segmentsInTier))
			break
		}

		budgetNumSegments += maxSegmentsPerTier
		totalSize -= int64(maxSegmentsPerTier) * tierSize
		tierSize = int64(float64(tierSize) * tierGrowth)
	}

	return budgetNumSegments
}

mergeplan.ScoreSegments.code:
func ScoreSegments(segments []Segment, o *MergePlanOptions) float64 {
	var totBeforeSize int64
	var totAfterSize int64
	var totAfterSizeFloored int64

	for _, segment := range segments {
		totBeforeSize += segment.FullSize()
		totAfterSize += segment.LiveSize()
		totAfterSizeFloored += o.RaiseToFloorSegmentSize(segment.LiveSize())
	}

	if totBeforeSize <= 0 || totAfterSize <= 0 || totAfterSizeFloored <= 0 {
		return 0
	}

	// Roughly guess the "balance" of the segments -- whether the
	// segments are about the same size.
	balance :=
		float64(o.RaiseToFloorSegmentSize(segments[0].LiveSize())) /
			float64(totAfterSizeFloored)

	// Gently favor smaller merges over bigger ones.  We don't want to
	// make the exponent too large else we end up with poor merges of
	// small segments in order to avoid the large merges.
	score := balance * math.Pow(float64(totAfterSize), 0.05)

	// Strongly favor merges that reclaim deletes.
	nonDelRatio := float64(totAfterSize) / float64(totBeforeSize)

	score *= math.Pow(nonDelRatio, o.ReclaimDeletesWeight)

	return score
}

bleve.SearchInContext.code:
func (i *indexImpl) SearchInContext(ctx context.Context, req *SearchRequest) (sr *SearchResult, err error) {
	i.mutex.RLock()
	defer i.mutex.RUnlock()

	searchStart := time.Now()

	if !i.open {
		return nil, ErrorIndexClosed
	}

	// open a reader for this search
	indexReader, err := i.i.Reader()
	if err != nil {
		return nil, fmt.Errorf("error opening index reader %v", err)
	}
	defer func() {
		if cerr := indexReader.Close(); err == nil && cerr != nil {
			err = cerr
		}
	}()

bleve.BatchIndex.code:
func (b *Batch) Index(id string, data interface{}) error {
	if id == "" {
		return ErrorEmptyID
	}
	if eventIndex, ok := b.index.(index.EventIndex); ok {
		eventIndex.FireIndexEvent()
	}
	doc := document.NewDocument(id)
	err := b.index.Mapping().MapDocument(doc, data)
	if err != nil {
		return err
	}
	b.internal.Update(doc)

	b.lastDocSize = uint64(doc.Size() +
		len(id) + size.SizeOfString) // overhead from internal
	b.totalSize += b.lastDocSize

	return nil
}

zapx.persist.code:
func PersistSegmentBase(sb *SegmentBase, path string) error {
	// since in-memory data is not processed by any writer callback,
	// check with the latest writer to see if data needs to be processed
	writer, err := NewFileWriter(nil, []byte(path))
	if err != nil {
		return err
	}
	if writer.id != sb.fileReader.id {
		// rewrite the segment base with the latest writer callback;
		// the rewrite will persist the segment to the given path (upon
		// success), so we should return early to avoid overwriting again.
		return rewriteSegmentBase(sb, path)
	}

	flag := os.O_RDWR | os.O_CREATE

	f, err := os.OpenFile(path, flag, 0600)
	if err != nil {
		return err
	}

	cleanup := func() {
		_ = f.Close()
		_ = os.Remove(path)
	}

	_, err = persistSegmentBaseToWriter(sb, f)
	if err != nil {
		cleanup()
		return err
	}

	err = f.Sync()
	if err != nil {
		cleanup()
		return err
	}

	err = f.Close()
	if err != nil {
		cleanup()
		return err
	}

	return err
}

